// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 timestamp) public {
        // Ensure block number is not divisible by 15 and timestamp increases
        vm.assume(blockNum % 15 != 0);
        vm.assume(timestamp > block.timestamp);

        // Set block parameters
        vm.roll(blockNum);
        vm.warp(timestamp);

        // Send exactly 10 ether via fallback
        (bool success, ) = address(c).call{value: 10 ether}("");
        assertTrue(success);

        // After call, because blockNum % 15 != 0, the transfer should NOT happen in reference
        // Contract should have balance of 10 ether
        assertTrue(address(c).balance == 10 ether);
    }
}

